/**
 *  HyperlinkSettingsDialog.js
 *
 *  Created on 04/23/24
 *
 */


if (Common === undefined)
    var Common = {};

var c_oHyperlinkType = {
    InternalLink:0,
    WebLink: 1
};

define('pdfeditor/main/app/view/HyperlinkSettingsDialog',[], function () { 'use strict';

    PDFE.Views.HyperlinkSettingsDialog = Common.UI.Window.extend(_.extend({

        initialize : function(options) {
            var _options = {};
            _.extend(_options, {
                title: this.textTitle,
                width: 350,
                style: 'min-width: 230px;',
                cls: 'modal-dlg',
                id: 'window-hyperlink-settings',
                buttons: ['ok', 'cancel']
            }, options || {});

            this.template = [
                '<div class="box" style="height: ' + (options.isAnnotation ? 280 : 330) + 'px;">',
                    '<div style="margin-bottom: 10px;">',
                        '<button type="button" class="btn btn-text-default auto" id="id-dlg-hyperlink-external">', this.textExternalLink,'</button>',
                        '<button type="button" class="btn btn-text-default auto" id="id-dlg-hyperlink-internal">', this.textInternalLink,'</button>',
                    '</div>',
                    '<div id="id-external-link">',
                        '<div class="input-row">',
                            '<label>' + this.strLinkTo + '</label>',
                        '</div>',
                        '<div id="id-dlg-hyperlink-url" class="input-row" style="margin-bottom: 5px;"></div>',
                    '</div>',
                    '<div id="id-internal-link" class="hidden">',
                        '<div class="input-row">',
                            '<label>' + this.strLinkTo + '</label>',
                        '</div>',
                        '<div id="id-dlg-hyperlink-list" style="width:100%; height: 171px;"></div>',
                        '<div id="id-dlg-hyperlink-chb-page" class="input-row" style="margin-top: 15px;"></div>',
                    '</div>',
                    '<div class="input-row not-annotation">',
                        '<label>' + this.strDisplay + '</label>',
                    '</div>',
                    '<div id="id-dlg-hyperlink-display" class="input-row not-annotation" style="margin-bottom: 5px;"></div>',
                    '<div class="input-row not-annotation">',
                        '<label>' + this.textTipText + '</label>',
                    '</div>',
                    '<div id="id-dlg-hyperlink-tip" class="input-row not-annotation" style="margin-bottom: 5px;"></div>',
                '</div>'
            ].join('');

            _options.tpl = _.template(this.template)(_options);
            this.slides = _options.slides;
            this.api = _options.api;
            this.urlType = AscCommon.c_oAscUrlType.Invalid;
            this.appOptions = _options.appOptions;
            this.isAnnotation = !!_options.isAnnotation;

            Common.UI.Window.prototype.initialize.call(this, _options);
        },

        render: function() {
            Common.UI.Window.prototype.render.call(this);

            var me = this,
                $window = this.getChild();

            me.btnExternal = new Common.UI.Button({
                el: $('#id-dlg-hyperlink-external'),
                enableToggle: true,
                toggleGroup: 'hyperlink-type',
                allowDepress: false,
                pressed: true
            });
            me.btnExternal.on('click', _.bind(me.onLinkTypeClick, me, c_oHyperlinkType.WebLink));

            me.btnInternal = new Common.UI.Button({
                el: $('#id-dlg-hyperlink-internal'),
                enableToggle: true,
                toggleGroup: 'hyperlink-type',
                allowDepress: false
            });
            me.btnInternal.on('click', _.bind(me.onLinkTypeClick, me, c_oHyperlinkType.InternalLink));

            Common.UI.GroupedButtons([me.btnExternal, me.btnInternal]);

            var config = {
                el          : $('#id-dlg-hyperlink-url'),
                allowBlank  : false,
                blankError  : me.txtEmpty,
                validateOnBlur: false,
                style       : 'width: 100%;',
                iconCls: 'toolbar__icon btn-browse',
                placeHolder: me.appOptions.isDesktopApp ? me.txtUrlPlaceholder : '',
                btnHint: me.textSelectFile,
                validation  : function(value) {
                    var trimmed = value.trim();
                    if (trimmed.length>2083) return me.txtSizeLimit;

                    me.urlType = me.api.asc_getUrlType(trimmed);
                    return (me.urlType!==AscCommon.c_oAscUrlType.Invalid) ? true : me.txtNotUrl;
                }
            };
            me.inputUrl = me.appOptions.isDesktopApp ? new Common.UI.InputFieldBtn(config) : new Common.UI.InputField(config);
            me.inputUrl._input.on('input', function (e) {
                me.isInputFirstChange && me.inputUrl.showError();
                me.isInputFirstChange = false;
                var val = $(e.target).val();
                if (me.isAutoUpdate) {
                    me.inputDisplay.setValue(val);
                    me.isTextChanged = true;
                }
                me.btnOk.setDisabled(val.trim()=='');
            });
            me.appOptions.isDesktopApp && me.inputUrl.on('button:click', _.bind(me.onSelectFile, me));

            me.inputDisplay = new Common.UI.InputField({
                el          : $('#id-dlg-hyperlink-display'),
                allowBlank  : true,
                validateOnBlur: false,
                style       : 'width: 100%;'
            }).on('changed:after', function() {
                me.isTextChanged = true;
            });
            me.inputDisplay._input.on('input', function (e) {
                me.isAutoUpdate = ($(e.target).val()=='');
            });

            me.inputTip = new Common.UI.InputField({
                el          : $('#id-dlg-hyperlink-tip'),
                style       : 'width: 100%;',
                maxLength   : Asc.c_oAscMaxTooltipLength
            });

            me.internalList = new Common.UI.TreeView({
                el: $('#id-dlg-hyperlink-list'),
                store: new Common.UI.TreeViewStore(),
                enableKeyEvents: true,
                tabindex: 1
            });
            me.internalList.on('item:select', _.bind(this.onSelectItem, this));

            me.chPageView = new Common.UI.CheckBox({
                el: $window.find('#id-dlg-hyperlink-chb-page'),
                labelText: this.txtPageView
            }).on('change', function(field, newValue, oldValue, eOpts){
                me.internalList.setDisabled(newValue==='checked');
                var rec = me.internalList.getSelectedRec();
                me.btnOk.setDisabled((!rec || rec.get('index')==4) && (newValue!=='checked'));
            });

            me.btnOk = _.find(this.getFooterButtons(), function (item) {
                return (item.$el && item.$el.find('.primary').addBack().filter('.primary').length>0);
            }) || new Common.UI.Button({ el: $window.find('.primary') });
            me.btnOk.setDisabled(true);

            $window.find('.dlg-btn').on('click', _.bind(this.onBtnClick, this));
            me.internalList.on('entervalue', _.bind(me.onPrimary, me));
            me.externalPanel = $window.find('#id-external-link');
            me.internalPanel = $window.find('#id-internal-link');

            if (me.isAnnotation) {
                $window.find('.not-annotation').addClass('hidden');
            } else
                me.chPageView.setVisible(false);
        },

        getFocusedComponents: function() {
            return [this.btnExternal, this.btnInternal, this.inputUrl, this.internalList, this.inputDisplay, this.inputTip, this.chPageView].concat(this.getFooterButtons());
        },

        setSettings: function (props) {
            if (props) {
                var me = this;

                var type = me.parseUrl(props.get_Value());
                (type == c_oHyperlinkType.WebLink) ? me.btnExternal.toggle(true) : me.btnInternal.toggle(true);
                me.ShowHideElem(type, props.get_Value());
                
                if (props.get_Text()!==null) {
                    me.inputDisplay.setValue(props.get_Text());
                    me.inputDisplay.setDisabled(false);
                    me.isAutoUpdate = (me.inputDisplay.getValue()=='' || type == c_oHyperlinkType.WebLink && me.inputUrl.getValue()==me.inputDisplay.getValue());
                } else {
                    this.inputDisplay.setValue(this.textDefault);
                    this.inputDisplay.setDisabled(true);
                }
                this.isTextChanged = false;
                this.inputTip.setValue(props.get_ToolTip());

                this.isAnnotation && this.chPageView.setValue(props.get_PageView());
                me._originalProps = props;
            } else {
                this.btnExternal.toggle(true);
                this.ShowHideElem(c_oHyperlinkType.WebLink);
            }
        },

        getSettings: function () {
            var me      = this,
                props   = new Asc.CHyperlinkProperty();
            var def_display = '',
                type = this.btnExternal.isActive() ? c_oHyperlinkType.WebLink : c_oHyperlinkType.InternalLink;
            if (type==c_oHyperlinkType.InternalLink) {//InternalLink
                var url = "ppaction://hlink";
                var tip = '';
                var txttip = me.inputTip.getValue();
                var rec = this.internalList.getSelectedRec();
                if (rec) {
                    url = url + rec.get('type');
                    tip = rec.get('tiptext');
                }
                props.put_Value( url );
                !this.isAnnotation && props.put_ToolTip(_.isEmpty(txttip) ? tip : txttip);
                def_display = tip;
            } else {
                var url = me.inputUrl.getValue().trim();
                if (me.urlType!==AscCommon.c_oAscUrlType.Unsafe && ! /(((^https?)|(^ftp)):\/\/)|(^mailto:)/i.test(url) )
                    url = ( (me.urlType==AscCommon.c_oAscUrlType.Email) ? 'mailto:' : 'http://' ) + url;
                url = url.replace(new RegExp("%20",'g')," ");
                props.put_Value( url );
                !this.isAnnotation && props.put_ToolTip(me.inputTip.getValue());
                def_display = url;
            }

            if (!me.inputDisplay.isDisabled() && (me.isTextChanged || _.isEmpty(me.inputDisplay.getValue()))) {
                if (_.isEmpty(me.inputDisplay.getValue()) || type==c_oHyperlinkType.WebLink && me.isAutoUpdate)
                    me.inputDisplay.setValue(def_display);
                !this.isAnnotation && props.put_Text(me.inputDisplay.getValue());
            }
            else
                !this.isAnnotation && props.put_Text(null);

            return props;
        },

        onBtnClick: function(event) {
            if (event.currentTarget && event.currentTarget.attributes['result'])
                this._handleInput(event.currentTarget.attributes['result'].value);
        },

        onPrimary: function(event) {
            this._handleInput('ok');
            return false;
        },

        _handleInput: function(state) {
            if (state === 'ok' && this.btnOk.isDisabled())
                return;

            if (this.options.handler) {
                if (state == 'ok') {
                    if (this.isAnnotation && this.btnInternal.isActive() && this.chPageView.getValue()==='checked') {
                        var me = this;
                        me.hide();

                        Common.NotificationCenter.trigger('editing:disable', true, {
                            viewMode: true,
                            allowSignature: false,
                            statusBar: true,
                            rightMenu: {clear: true, disable: true},
                            leftMenu: {disable: true, previewMode: true},
                            fileMenu: {protect: true},
                            navigation: {disable: true, previewMode: true},
                            comments: {disable: true, previewMode: true},
                            chat: true,
                            viewport: true,
                            documentHolder: {clear: true, disable: true},
                            toolbar: true,
                            plugins: false,
                            header: {docmode: true, search: true},
                            shortcuts: true
                        }, 'setlink');
                        me.api.SetCanInteract(false);
                        Common.UI.alert({
                            modal: false,
                            maxwidth: 400,
                            title: this.txtCreateLink,
                            msg: this.txtCreateDesc,
                            buttons: [  {caption: this.txtSetLink, primary: true, value: 'ok'},
                                'cancel'],
                            callback: function(btn){
                                if (btn === 'ok') {
                                    me.options.handler.call(me, me, 'view');
                                }
                                me.close();
                                Common.NotificationCenter.trigger('editing:disable', false, {
                                    viewMode: false,
                                    allowSignature: false,
                                    statusBar: true,
                                    rightMenu: {clear: true, disable: true},
                                    leftMenu: {disable: true, previewMode: true},
                                    fileMenu: {protect: true},
                                    navigation: {disable: true, previewMode: true},
                                    comments: {disable: true, previewMode: true},
                                    chat: true,
                                    viewport: true,
                                    documentHolder: {clear: true, disable: true},
                                    toolbar: true,
                                    plugins: false,
                                    header: {docmode: true, search: true},
                                    shortcuts: true
                                }, 'setlink');
                                me.api.SetCanInteract(true);
                            }
                        });
                        return;
                    }

                    var checkurl = (this.btnExternal.isActive()) ? this.inputUrl.checkValidate() : true;
                    if (checkurl !== true)  {
                        this.isInputFirstChange = true;
                        this.inputUrl.focus();
                        return;
                    }
                    if (!this.isAnnotation) {
                        var checkdisp = this.inputDisplay.checkValidate();
                        if (checkdisp !== true) {
                            this.inputDisplay.focus();
                            return;
                        }
                        !this._originalProps.get_Value() &&  Common.Utils.InternalSettings.set("pdfe-settings-link-type", this.btnInternal.isActive());
                    }
                }
                this.options.handler.call(this, this, state);
            }

            this.close();
        },

        ShowHideElem: function(value, url) {
            this.externalPanel.toggleClass('hidden', value !== c_oHyperlinkType.WebLink);
            this.internalPanel.toggleClass('hidden', value !== c_oHyperlinkType.InternalLink);
            if (value==c_oHyperlinkType.InternalLink) {
                if (url===null || url===undefined || url=='' )
                    url = "ppaction://hlinkshowjump?jump=firstslide";
                var store = this.internalList.store;
                if (store.length<1) {
                    var arr = [], i = 0;
                    arr.push(new Common.UI.TreeViewModel({
                        name : this.txtFirst,
                        level: 0,
                        index: i++,
                        hasParent: false,
                        isEmptyItem: false,
                        isNotHeader: true,
                        hasSubItems: false,
                        type: "showjump?jump=firstslide",
                        tiptext: this.txtFirst,
                        selected: url == "ppaction://hlinkshowjump?jump=firstslide"
                    }));
                    arr.push(new Common.UI.TreeViewModel({
                        name : this.txtLast,
                        level: 0,
                        index: i++,
                        hasParent: false,
                        isEmptyItem: false,
                        isNotHeader: true,
                        hasSubItems: false,
                        type: "showjump?jump=lastslide",
                        tiptext: this.txtLast,
                        selected: url == "ppaction://hlinkshowjump?jump=lastslide"
                    }));
                    arr.push(new Common.UI.TreeViewModel({
                        name : this.txtNext,
                        level: 0,
                        index: i++,
                        hasParent: false,
                        isEmptyItem: false,
                        isNotHeader: true,
                        hasSubItems: false,
                        type: "showjump?jump=nextslide",
                        tiptext: this.txtNext,
                        selected: url == "ppaction://hlinkshowjump?jump=nextslide"
                    }));
                    arr.push(new Common.UI.TreeViewModel({
                        name : this.txtPrev,
                        level: 0,
                        index: i++,
                        hasParent: false,
                        isEmptyItem: false,
                        isNotHeader: true,
                        hasSubItems: false,
                        type: "showjump?jump=previousslide",
                        tiptext: this.txtPrev,
                        selected: url == "ppaction://hlinkshowjump?jump=previousslide"
                    }));
                    arr.push(new Common.UI.TreeViewModel({
                        name : this.textPages,
                        level: 0,
                        index: i++,
                        hasParent: false,
                        isEmptyItem: false,
                        isNotHeader: true,
                        hasSubItems: this.api.getCountPages()>0
                    }));
                    var mask = "ppaction://hlinksldjumpslide",
                        indSlide = url.indexOf(mask),
                        slideNum = (0 == indSlide) ? parseInt(url.substring(mask.length)) : -1;
                    for (var i=0; i<this.api.getCountPages(); i++) {
                        arr.push(new Common.UI.TreeViewModel({
                            name : this.txtPage + ' ' + (i+1),
                            level: 1,
                            index: arr.length,
                            hasParent: false,
                            isEmptyItem: false,
                            isNotHeader: true,
                            hasSubItems: false,
                            type: 'sldjumpslide' + i,
                            tiptext: this.txtPage + ' ' + (i+1),
                            selected: i==slideNum
                        }));
                    }
                    store.reset(arr);
                }
                var rec = this.internalList.getSelectedRec();
                rec && this.internalList.scrollToRecord(rec);
                this.btnOk.setDisabled((!rec || rec.get('index')==4) && !(this.isAnnotation && this.chPageView.getValue()==='checked'));
                var me = this;
                _.delay(function(){
                    me.inputDisplay.focus();
                },50);
            } else {
                this.btnOk.setDisabled(this.inputUrl.getValue().trim()=='');
                var me = this;
                _.delay(function(){
                    me.inputUrl.focus();
                },50);
            }
        },

        onLinkTypeClick: function(type, btn, event) {
            this.ShowHideElem(type);
            if (this.isAutoUpdate) {
                if (type==c_oHyperlinkType.InternalLink) {
                    var rec = this.internalList.getSelectedRec();
                    this.inputDisplay.setValue(rec && (rec.get('level') || rec.get('index')<4) ? rec.get('name') : '');
                } else {
                    this.inputDisplay.setValue(this.inputUrl.getValue());
                }
                this.isTextChanged = true;
            }
        },

        parseUrl: function(url) {
            if (url===null || url===undefined || url=='' )
                return Common.Utils.InternalSettings.get("pdfe-settings-link-type") ? c_oHyperlinkType.InternalLink : c_oHyperlinkType.WebLink;

            var indAction = url.indexOf("ppaction://hlink");
            if (0 == indAction)
            {
                return c_oHyperlinkType.InternalLink;
            } else  {
                this.inputUrl.setValue(url ? url.replace(new RegExp(" ",'g'), "%20") : '');
                return c_oHyperlinkType.WebLink;
            }
        },

        onSelectItem: function(picker, item, record, e){
            if (!record) return;
            this.btnOk.setDisabled(record.get('index')==4 && !(this.isAnnotation && this.chPageView.getValue()==='checked'));
            if (this.isAutoUpdate) {
                this.inputDisplay.setValue((record.get('level') || record.get('index')<4) ? record.get('name') : '');
                this.isTextChanged = true;
            }
        },

        onSelectFile: function() {
            var me = this;
            if (me.api) {
                var callback = function(result) {
                    if (result) {
                        me.inputUrl.setValue(result);
                        if (me.inputUrl.checkValidate() !== true)
                            me.isInputFirstChange = true;
                        if (me.isAutoUpdate) {
                            me.inputDisplay.setValue(result);
                            me.isTextChanged = true;
                        }
                        me.btnOk.setDisabled(result.trim()=='');
                    }
                };

                me.api.asc_getFilePath(callback); // change sdk function
            }
        },

        textTitle:          'Hyperlink Settings',
        textInternalLink:   'Place in Document',
        textExternalLink:   'External Link',
        textEmptyLink:      'Enter link here',
        textEmptyDesc:      'Enter caption here',
        textEmptyTooltip:   'Enter tooltip here',
        txtPage:            'Page',
        strDisplay:         'Display',
        textTipText:        'Screen Tip Text',
        strLinkTo:          'Link To',
        txtEmpty:           'This field is required',
        txtNotUrl:          'This field should be a URL in the format \"http://www.example.com\"',
        txtNext:            'Next Page',
        txtPrev:            'Previous Page',
        txtFirst:           'First Page',
        txtLast:            'Last Page',
        textDefault:        'Selected text',
        textPages: 'Pages',
        txtSizeLimit: 'This field is limited to 2083 characters',
        txtUrlPlaceholder: 'Enter the web address or select a file',
        textSelectFile: 'Select file'
    }, PDFE.Views.HyperlinkSettingsDialog || {}))
});

define('text!pdfeditor/main/app/template/ShapeSettingsAdvanced.template',[],function () { return '<div id="id-adv-shape-general" class="settings-panel active">\n    <div class="inner-content">\n    <table cols="1" width="100%">\n        <tr>\n            <td class="padding-large">\n                <label class="header"><%= scope.textShapeName %></label>\n                <div id="shape-general-object-name"></div>\n            </td>\n        </tr>\n    </table>\n    </div>\n</div>\n<div id="id-adv-shape-width" class="settings-panel active">\n    <div class="inner-content">\n        <table cols="3">\n            <tr>\n                <td colspan="3" width="88px" class="padding-small">\n                    <label class="header"><%= scope.textSize %></label>\n                </td>\n            </tr>\n            <tr>\n                <td width="93px">\n                    <label class="input-label"><%= scope.textWidth %></label>\n                    <div id="shape-advanced-spin-width"></div>\n                </td>\n                <td width="28px" style="vertical-align: bottom;">\n                    <div id="shape-advanced-button-ratio"></div>\n                </td>\n                <td width="93px">\n                    <label class="input-label"><%= scope.textHeight %></label>\n                    <div id="shape-advanced-spin-height"></div>\n                </td>\n            </tr>\n        </table>\n    </div>\n    <div class="padding-large"></div>\n    <div class="inner-content">\n        <table cols="2" style="width: 100%;">\n            <tr>\n                <td colspan="4" width="88px" class="padding-small">\n                    <label class="header"><%= scope.textPosition %></label>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small" width="121px">\n                    <label class="input-label"><%= scope.textHorizontal %></label>\n                    <div id="shape-advanced-spin-x"></div>\n                </td>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textFrom %></label>\n                    <div id="shape-advanced-combo-from-x"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textVertical %></label>\n                    <div id="shape-advanced-spin-y"></div>\n                </td>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textFrom %></label>\n                    <div id="shape-advanced-combo-from-y"></div>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>\n<div id="id-adv-shape-rotate" class="settings-panel active">\n    <div class="inner-content  padding-large">\n        <div style="width: 100%;">\n            <label class="input-label"><%= scope.textAngle %></label>\n            <div id="shape-advanced-spin-angle" class="margin-left-5" style="display: inline-block;"></div>\n        </div>\n    </div>\n    <div class="separator horizontal padding-large"></div>\n    <div class="inner-content  padding-large">\n        <table cols="2">\n            <tr>\n                <td rowspan="2" class="padding-small" style="vertical-align: top;">\n                    <label class="input-label margin-right-15" style="vertical-align: top;"><%= scope.textFlipped %></label>\n                </td>\n                <td class="padding-small">\n                    <div id="shape-advanced-checkbox-hor"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <div id="shape-advanced-checkbox-vert"></div>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>\n<div id="id-adv-shape-shape" class="settings-panel">\n    <div class="inner-content">\n        <table cols="2" style="width: 100%;">\n            <tr>\n                <td colspan=2 class="padding-small">\n                    <label class="header"><%= scope.textLineStyle %></label>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-large" width="125px">\n                    <label class="input-label"><%= scope.textCapType %></label>\n                    <div id="shape-advanced-cap-type" style="width: 100px;"></div>\n                </td>\n                <td class="padding-large">\n                    <label class="input-label"><%= scope.textJoinType %></label>\n                    <div id="shape-advanced-join-type" style="width: 100px;"></div>\n                </td>\n            </tr>\n        </table>\n    </div>\n    <div class="separator horizontal padding-large"></div>\n    <div class="inner-content">\n        <table cols="2" style="width: 100%;">\n            <tr>\n                <td colspan=2 class="padding-small">\n                    <label class="header"><%= scope.textArrows %></label>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small" width="125px">\n                    <label class="input-label"><%= scope.textBeginStyle %></label>\n                    <div id="shape-advanced-begin-style" style="width: 100px;"></div>\n                </td>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textEndStyle %></label>\n                    <div id="shape-advanced-end-style" style="width: 100px;"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textBeginSize %></label>\n                    <div id="shape-advanced-begin-size" style="width: 100px;"></div>\n                </td>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textEndSize %></label>\n                    <div id="shape-advanced-end-size" style="width: 100px;"></div>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>\n<div id="id-adv-shape-margins" class="settings-panel">\n    <div class="inner-content">\n        <table cols="1" style="width: 100%;">\n            <tr>\n                <td class="padding-small">\n                    <label class="header"><%= scope.textAutofit %></label>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <div id="shape-radio-nofit"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <div id="shape-radio-shrink"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-large">\n                    <div id="shape-radio-fit"></div>\n                </td>\n            </tr>\n        </table>\n        <div class="separator horizontal padding-large"></div>\n        <table cols="2" style="width: 100%;">\n            <tr>\n                <td colspan=2 class="padding-small">\n                    <label class="header"><%= scope.strMargins %></label>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small" width="125px">\n                    <label class="input-label"><%= scope.textTop %></label>\n                    <div id="shape-margin-top"></div>\n                </td>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textLeft %></label>\n                    <div id="shape-margin-left"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textBottom %></label>\n                    <div id="shape-margin-bottom"></div>\n                </td>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textRight %></label>\n                    <div id="shape-margin-right"></div>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>\n<div id="id-adv-shape-columns" class="settings-panel">\n    <div class="inner-content">\n        <table cols="1" style="width: 100%;">\n            <tr>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textColNumber %></label>\n                    <div id="shape-columns-number"></div>\n                </td>\n            </tr>\n            <tr>\n                <td class="padding-small">\n                    <label class="input-label"><%= scope.textSpacing %></label>\n                    <div id="shape-columns-spacing"></div>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>\n<div id="id-adv-shape-alttext" class="settings-panel">\n    <div class="inner-content">\n        <table cols="1" width="100%">\n            <tr>\n                <td class="padding-large">\n                    <label class="header"><%= scope.textAltTitle %></label>\n                    <div id="shape-advanced-alt-title"></div>\n                </td>\n            </tr>\n            <tr>\n                <td>\n                    <label class="header"><%= scope.textAltDescription %></label>\n                    <textarea id="shape-advanced-alt-description" class="form-control" style="width: 100%; height: 70px;"></textarea>\n                </td>\n            </tr>\n            <tr>\n                <td>\n                    <label><%= scope.textAltTip %></label>\n                </td>\n            </tr>\n        </table>\n    </div>\n</div>';});

